function t4(title, o){ return Object.assign({kind:`Fuente`, title:`Concilio de Trento, ses. IV, ${title}`, date:`8 abr 1546 (sin confirmar: verificación 2, J5)`, year:1546, ed:ED.ayala, url:LINKS.ayala}, o); }
function df(title, o){ return Object.assign({kind:`Fuente`, title:`Concilio Vaticano I, Dei Filius, ${title}`, date:`24 abr 1870`, year:1870, ed:ED.df, url:LINKS.df}, o); }
function dv(n, o){ return Object.assign({kind:`Fuente`, title:`Concilio Vaticano II, Dei Verbum ${n}`, date:`18 nov 1965`, year:1965, ed:ED.vat2, url:LINKS.dv}, o); }
function cec(n, page, o){
  const nn = String(n);
  const s = {kind:`Fuente`, title:`Catecismo de la Iglesia Católica, ${/[–,y]/.test(nn) ? `nn.` : `n.`} ${nn}`, date:`1992/1997`, year:1992, ed:ED.cec};
  if (page) s.url = {href:CECB + page + `_sp.html`, label:LEER};
  return Object.assign(s, o || {});
}
function cic(n, file, o){
  return Object.assign({kind:`Fuente`, title:`Código de Derecho Canónico, ${/[–,y]/.test(String(n)) ? `cann.` : `can.`} ${n}`, date:`1983`, year:1983, ed:ED.cic, url:{href:CICB + file + `_sp.html`, label:LEER}}, o || {});
}
function sc(n, o){ return Object.assign({kind:`Fuente`, title:`Concilio Vaticano II, Sacrosanctum Concilium ${n}`, date:`4 dic 1963`, year:1963, ed:ED.vat2}, o); }
function vd(n, o){ return Object.assign({kind:`Fuente`, title:`Benedicto XVI, Verbum Domini ${n}`, date:`30 sep 2010`, year:2010, ed:ED.vd}, o); }
function lut(title, o){ return Object.assign({kind:`Texto de otra tradición`, title, ed:ED.triglot, url:LINKS.triglot}, o); }
function wcf(title, o){ return Object.assign({kind:`Texto de otra tradición`, title, date:`1647`, year:1647, ed:ED.wcf, url:LINKS.wcf1880}, o); }
function wcat(title, o){ return Object.assign({kind:`Texto de otra tradición`, title, date:`1647`, year:1647, ed:ED.wcat, url:LINKS.wcf}, o); }

